import axios from 'axios';
import authHeader from './authHeader';

const API_URL = '/api/phones';

// 获取所有手机
const getPhones = async () => {
    const response = await axios.get(API_URL);
    return response.data;
};

// 获取单个手机
const getPhoneById = async (id) => {
    const response = await axios.get(`${API_URL}/${id}`);
    return response.data;
};

// 创建手机 (管理员)
const createPhone = async (formData) => {
    const response = await axios.post(API_URL, formData, {
        headers: {
            ...authHeader(),
            'Content-Type': 'multipart/form-data',
        },
    });
    return response.data;
};

// 更新手机 (管理员)
const updatePhone = async (id, formData) => {
    const response = await axios.put(`${API_URL}/${id}`, formData, {
        headers: {
            ...authHeader(),
            'Content-Type': 'multipart/form-data',
        },
    });
    return response.data;
};

// 删除手机 (管理员)
const deletePhone = async (id) => {
    await axios.delete(`${API_URL}/${id}`, { headers: authHeader() });
};

// 添加到收藏
const addToFavorite = async (id) => {
    await axios.post(`${API_URL}/${id}/favorite`, {}, { headers: authHeader() });
};

// 从收藏中移除
const removeFromFavorite = async (id) => {
    await axios.delete(`${API_URL}/${id}/favorite`, { headers: authHeader() });
};

const phoneService = {
    getPhones,
    getPhoneById,
    createPhone,
    updatePhone,
    deletePhone,
    addToFavorite,
    removeFromFavorite,
};

export default phoneService;
